#include <windows.h>
#include <stdio.h>

int main() {
    STARTUPINFOW startup = { sizeof(startup) };
    PROCESS_INFORMATION process = {};
    wchar_t command[] = L"cmd.exe /c exit 0";

    if (!CreateProcessW(nullptr, command, nullptr, nullptr, FALSE,
