#include <windows.h>
#include <shellapi.h>
#include <stdio.h>

#pragma comment(lib, "shell32.lib")

int main() {
    HINSTANCE result = ShellExecuteA(nullptr, "open", "cmd.exe", "/c exit 0",
        nullptr, SW_HIDE);
    if (reinterpret_cast<INT_PTR>(result) <= 32) {
        printf("ShellExecuteA failed: %lld\n",
            static_cast<long long>(reinterpret_cast<INT_PTR>(result)));
    }
    return 0;
}

#include <windows.h>
#include <shellapi.h>
#include <stdio.h>

#pragma comment(lib, "shell32.lib")

int main() {
    SHELLEXECUTEINFOA info = { sizeof(info) };
    info.fMask = SEE_MASK_NOCLOSEPROCESS;
    info.lpVerb = "open";
    info.lpFile = "cmd.exe";
    info.lpParameters = "/c exit 0";
    info.nShow = SW_HIDE;

    if (!ShellExecuteExA(&info)) {
        return 1;
    }

    if (info.hProcess != nullptr) {
        WaitForSingleObject(info.hProcess, 5000);
        CloseHandle(info.hProcess);
    }
    return 0;
}

